CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', persona TEXT NOT NULL DEFAULT '', class_name TEXT NOT NULL DEFAULT '', board TEXT NOT NULL DEFAULT '', profession TEXT NOT NULL DEFAULT '', work_format TEXT NOT NULL DEFAULT '', subjects TEXT NOT NULL DEFAULT '[]', skills TEXT NOT NULL DEFAULT '[]', goals TEXT NOT NULL DEFAULT '[]', blockers TEXT NOT NULL DEFAULT '[]', level TEXT NOT NULL DEFAULT '', wake TEXT NOT NULL DEFAULT '06:30', sleep TEXT NOT NULL DEFAULT '22:30', school_hours TEXT NOT NULL DEFAULT '', work_hours TEXT NOT NULL DEFAULT '', coins INTEGER NOT NULL DEFAULT 0, xp INTEGER NOT NULL DEFAULT 0, timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata', onboarding_complete INTEGER NOT NULL DEFAULT 0, theme TEXT NOT NULL DEFAULT 'sky', motion TEXT NOT NULL DEFAULT 'full', environment TEXT NOT NULL DEFAULT 'calm', widgets TEXT NOT NULL DEFAULT '["stats","coach","plan","weekly"]', ai_suggestions INTEGER NOT NULL DEFAULT 1, ambient TEXT NOT NULL DEFAULT 'rain', sounds INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'Study', repeat_days TEXT NOT NULL DEFAULT '[]', completed_dates TEXT NOT NULL DEFAULT '[]', date TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS habits (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL, icon TEXT NOT NULL DEFAULT 'star', frequency TEXT NOT NULL DEFAULT 'daily', target INTEGER NOT NULL DEFAULT 1, completed_dates TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS focus_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, started_at TEXT NOT NULL, duration_sec INTEGER NOT NULL, mode TEXT NOT NULL DEFAULT 'focus', subject TEXT NOT NULL DEFAULT '', completed INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS resources (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'note', category TEXT NOT NULL DEFAULT 'General', url TEXT NOT NULL DEFAULT '', file_key TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS coach_messages (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL);
